191	ColorRGBA GLVolume::brighten_color(const ColorRGBA& color, float multiplier)
192	{
193	    // Convert RGB to HSL, increase lightness, convert back
194	
195	    float r = color.r(), g = color.g(), b = color.b();
196	
197	    // RGB to HSL conversion
198	    float max_val = std::max({r, g, b});
199	    float min_val = std::min({r, g, b});
200	    float l = (max_val + min_val) / 2.0f;
201	    float h = 0.0f, s = 0.0f;
202	
203	    if (max_val != min_val) {
204	        float delta = max_val - min_val;
205	        s = l > 0.5f ? delta / (2.0f - max_val - min_val) : delta / (max_val + min_val);
206	
207	        if (max_val == r)
208	            h = (g - b) / delta + (g < b ? 6.0f : 0.0f);
209	        else if (max_val == g)
210	            h = (b - r) / delta + 2.0f;
211	        else
212	            h = (r - g) / delta + 4.0f;
213	        h /= 6.0f;
214	    }
215	
216	    // Increase lightness by a fixed amount (0.25)
217	    // Ensures even saturated colors become visibly brighter
218	    l = std::min(l + 0.25f, 1.0f);
219	
220	    // HSL to RGB conversion
221	    auto hue_to_rgb = [](float p, float q, float t) {
222	        if (t < 0.0f) t += 1.0f;
223	        if (t > 1.0f) t -= 1.0f;
224	        if (t < 1.0f / 6.0f) return p + (q - p) * 6.0f * t;
225	        if (t < 1.0f / 2.0f) return q;
226	        if (t < 2.0f / 3.0f) return p + (q - p) * (2.0f / 3.0f - t) * 6.0f;
227	        return p;
228	    };
229	
230	    if (s == 0.0f) {
231	        r = g = b = l; // achromatic (gray)
232	    } else {
233	        float q = l < 0.5f ? l * (1.0f + s) : l + s - l * s;
234	        float p = 2.0f * l - q;
235	        r = hue_to_rgb(p, q, h + 1.0f / 3.0f);
236	        g = hue_to_rgb(p, q, h);
237	        b = hue_to_rgb(p, q, h - 1.0f / 3.0f);
238	    }
239	
240	    return ColorRGBA(r, g, b, color.a());
241	}
